    /** Six hex characters per integer, in order. */
    private fun decode(hex: String): IntArray {
        val out = IntArray(hex.length / 6)
        for (index in out.indices) {
            out[index] = hex.substring(index * 6, index * 6 + 6).toInt(16)
        }
        return out
    }
